window.docContents[146].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___10___-Frobenius-determinant/Frobenius-determinant-_LPAR_group-determinant_RPAR_/#Chapter4___Definition4___10___1":{"contents":"Definition 4.10.1. Consider the matrix X_G with entries a_{ij} = x_{g_i g_j}. The determinant of X_G is some polynomial of degree n of x_{g_1}, x_{g_2}, \\ldots, x_{g_n} that is called the Frobenius determinant, or group determinant.\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.10. Frobenius determinant\tFrobenius determinant (group determinant)","header":"Frobenius determinant (group determinant)","id":"/4___-Representations-of-finite-groups___-Basic-results/4___10___-Frobenius-determinant/Frobenius-determinant-_LPAR_group-determinant_RPAR_/#Chapter4___Definition4___10___1"},"/5___-Representations-of-finite-groups___-Further-results/5___27___-Representations-of-semidirect-products/Section-5___27___-Representations-of-semidirect-products/#Chapter5___Introduction_5___27___heading-1":{"contents":"","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.27. Representations of semidirect products\tSection 5.27: Representations of semidirect products","header":"5.27. Representations of semidirect products","id":"/5___-Representations-of-finite-groups___-Further-results/5___27___-Representations-of-semidirect-products/Section-5___27___-Representations-of-semidirect-products/#Chapter5___Introduction_5___27___heading-1"}});
